<?php $value = static fn(string $key) => old($key, $finding[$key] ?? ''); ?>
<div class="mx-auto max-w-4xl"><div class="page-heading"><div><a href="<?= e(url('/hallazgos')) ?>" class="text-link mb-3"><?= icon('arrow-left', 'h-3.5 w-3.5') ?> Volver a hallazgos</a><span class="eyebrow block">Actuar · Mejora continua</span><h1>Editar hallazgo #<?= (int) $finding['id'] ?></h1><p>Actualiza la acción sin cambiar el estado <?= e($finding['estado']) ?> ni la fecha de cierre.</p></div><span class="metric-icon bg-amber-50 text-amber-600"><?= icon('edit', 'h-5 w-5') ?></span></div><form method="post" action="<?= e(url('/hallazgos/' . $finding['id'])) ?>" class="ios-card mt-6 grid gap-5 p-5 sm:grid-cols-2 sm:p-7"><?= csrf_field() ?><div><label class="label">Origen *</label><select name="origen" class="input"><?php foreach (['Auditoria','Inspeccion','Accidente','Reporte'] as $origin): ?><option value="<?= e($origin) ?>"<?= selected($value('origen'), $origin) ?>><?= e($origin) ?></option><?php endforeach; ?></select><?= field_error('origen') ?></div><div><label class="label">Responsable *</label><input name="responsable" class="input" maxlength="250" value="<?= e($value('responsable')) ?>" required><?= field_error('responsable') ?></div><div class="sm:col-span-2"><label class="label">Descripción del hallazgo *</label><textarea name="descripcion" class="input min-h-28" maxlength="3000" required><?= e($value('descripcion')) ?></textarea><?= field_error('descripcion') ?></div><div class="sm:col-span-2"><label class="label">Acción correctiva *</label><textarea name="accion_correctiva" class="input min-h-28" maxlength="3000" required><?= e($value('accion_correctiva')) ?></textarea><?= field_error('accion_correctiva') ?></div><div><label class="label">Fecha límite *</label><input name="fecha_limite" type="date" class="input" value="<?= e($value('fecha_limite')) ?>" required><?= field_error('fecha_limite') ?></div><div class="flex items-end justify-end gap-3"><a href="<?= e(url('/hallazgos')) ?>" class="btn-secondary">Cancelar</a><button type="submit" class="btn-primary">Guardar cambios</button></div></form></div>
